package de.pelzig.settlement.fees;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Objects;

/**
* Interchange-plus fee calculator. Stateless; safe for use in a shared bean.
*/
public final class InterchangePlusCalculator {

private final BigDecimal markupBps;

public InterchangePlusCalculator(BigDecimal markupBps) {
this.markupBps = Objects.requireNonNull(markupBps);
}

public BigDecimal feeFor(BigDecimal amount, BigDecimal interchangeBps) {
BigDecimal totalBps = interchangeBps.add(markupBps);
return amount.multiply(totalBps)
.divide(BigDecimal.valueOf(10_000L), 4, RoundingMode.HALF_UP);
}
}

