use std::time::Duration;
use tokio::sync::mpsc;
use tokio::time;

#[derive(Debug, Clone)]
pub struct HeartbeatConfig {
pub interval: Duration,
pub timeout: Duration,
pub max_missed: u32,
}

impl Default for HeartbeatConfig {
fn default() -> Self {
Self {
interval: Duration::from_secs(15),
timeout: Duration::from_secs(5),
max_missed: 3,
}
}
}

pub enum Event {
Healthy { latency_ms: u64 },
Missed { consecutive: u32 },
Dead,
}

pub async fn run_heartbeat<F, Fut>(
cfg: HeartbeatConfig,
mut probe: F,
tx: mpsc::Sender<Event>,
)
where
F: FnMut() -> Fut,
Fut: std::future::Future<Output = Result<u64, ()>>,
{
let mut consecutive_miss = 0u32;
let mut ticker = time::interval(cfg.interval);
loop {
ticker.tick().await;
let started = time::Instant::now();
match time::timeout(cfg.timeout, probe()).await {
Ok(Ok(_)) => {
consecutive_miss = 0;
let _ = tx
.send(Event::Healthy {
latency_ms: started.elapsed().as_millis() as u64,
})
.await;
}
_ => {
consecutive_miss += 1;
if consecutive_miss >= cfg.max_missed {
let _ = tx.send(Event::Dead).await;
return;
}
let _ = tx
.send(Event::Missed {
consecutive: consecutive_miss,
})
.await;
}
}
}
}

