import pandas as pd
import numpy as np

def winsorize(series: pd.Series, lower: float = 0.01, upper: float = 0.99) -> pd.Series:
if not (0.0 <= lower < upper <= 1.0):
raise ValueError("quantile bounds out of range")
lo, hi = series.quantile([lower, upper])
return series.clip(lower=lo, upper=hi)

def rolling_zscore(series: pd.Series, window: int, min_periods: int | None = None) -> pd.Series:
if window <= 1:
raise ValueError("window must be > 1")
if min_periods is None:
min_periods = max(window // 2, 2)
mean = series.rolling(window=window, min_periods=min_periods).mean()
std = series.rolling(window=window, min_periods=min_periods).std(ddof=0)
out = (series - mean) / std.replace(0, np.nan)
return out

def session_id(timestamps: pd.Series, gap_minutes: int = 30) -> pd.Series:
if not isinstance(timestamps, pd.Series):
raise TypeError("timestamps must be a pandas Series of datetimes")
ts = pd.to_datetime(timestamps).sort_values()
gap = ts.diff() > pd.Timedelta(minutes=gap_minutes)
return gap.cumsum().astype(np.int64).rename("session_id")

def safe_join(left: pd.DataFrame, right: pd.DataFrame, on: str | list[str], how: str = "left") -> pd.DataFrame:
keys = [on] if isinstance(on, str) else list(on)
left_dup = left.duplicated(subset=keys).sum()
right_dup = right.duplicated(subset=keys).sum()
if left_dup or right_dup:
raise ValueError(f"duplicate keys: left={left_dup}, right={right_dup}")
return left.merge(right, on=keys, how=how, validate="one_to_one")

