from collections import deque
from typing import Hashable, Iterable, TypeVar

Node = TypeVar("Node", bound=Hashable)

def topological_sort(nodes: Iterable[Node], edges: Iterable[tuple[Node, Node]]) -> list[Node]:
indeg: dict[Node, int] = {n: 0 for n in nodes}
adj: dict[Node, list[Node]] = {n: [] for n in indeg}
for u, v in edges:
if u not in adj:
adj[u] = []
indeg[u] = indeg.get(u, 0)
if v not in indeg:
indeg[v] = 0
adj[v] = []
adj[u].append(v)
indeg[v] += 1

q = deque([n for n, d in indeg.items() if d == 0])
out: list[Node] = []
while q:
n = q.popleft()
out.append(n)
for m in adj[n]:
indeg[m] -= 1
if indeg[m] == 0:
q.append(m)
if len(out) != len(indeg):
raise ValueError("cycle detected")
return out

def strongly_connected(nodes: Iterable[Node], edges: Iterable[tuple[Node, Node]]) -> list[list[Node]]:
adj: dict[Node, list[Node]] = {n: [] for n in nodes}
rev: dict[Node, list[Node]] = {n: [] for n in nodes}
for u, v in edges:
adj.setdefault(u, []).append(v)
rev.setdefault(v, []).append(u)
adj.setdefault(v, adj.get(v, []))
rev.setdefault(u, rev.get(u, []))

visited: set[Node] = set()
order: list[Node] = []

def dfs1(start: Node) -> None:
stack = [(start, iter(adj.get(start, [])))]
visited.add(start)
while stack:
node, it = stack[-1]
try:
nxt = next(it)
if nxt not in visited:
visited.add(nxt)
stack.append((nxt, iter(adj.get(nxt, []))))
except StopIteration:
order.append(node)
stack.pop()

for n in list(adj.keys()):
if n not in visited:
dfs1(n)

comps: list[list[Node]] = []
seen: set[Node] = set()
for n in reversed(order):
if n in seen:
continue
stack = [n]
comp = []
seen.add(n)
while stack:
x = stack.pop()
comp.append(x)
for y in rev.get(x, []):
if y not in seen:
seen.add(y)
stack.append(y)
comps.append(comp)
return comps

protected final void fastPathOrderedEmit(U value, boolean delayError, Disposable disposable) {
final Observer<? super V> observer = downstream;
final SimplePlainQueue<U> q = queue;

if (wip.get() == 0 && wip.compareAndSet(0, 1)) {
if (q.isEmpty()) {
accept(observer, value);
if (leave(-1) == 0) {
return;
}
} else {
q.offer(value);
}
} else {
q.offer(value);
if (!enter()) {
return;
}
}
QueueDrainHelper.drainLoop(q, observer, delayError, disposable, this);
}

protected function fillRouteParams(string $from, array $params = null): string
{
// Find all of our back-references in the original route
preg_match_all('/\(([^)]+)\)/', $from, $matches);

if (empty($matches[0]))
{
return '/' . ltrim($from, '/');
}

// Build our resulting string, inserting the $params in
// the appropriate places.
foreach ($matches[0] as $index => $pattern)
{
// Ensure that the param we're inserting matches
// the expected param type.
$pos = strpos($from, $pattern);

if (preg_match("|{$pattern}|", $params[$index]))
{
$from = substr_replace($from, $params[$index], $pos, strlen($pattern));
}
else
{
throw RouterException::forInvalidParameterType();
}
}

return '/' . ltrim($from, '/');
}

