use std::collections::HashMap;
use std::sync::{Mutex, MutexGuard};
use std::time::{Duration, Instant};

pub struct Bucket {
capacity: f64,
refill_per_sec: f64,
tokens: f64,
last: Instant,
}

impl Bucket {
pub fn new(capacity: f64, refill_per_sec: f64) -> Self {
Self { capacity, refill_per_sec, tokens: capacity, last: Instant::now() }
}

fn refill(&mut self, now: Instant) {
let elapsed = now.duration_since(self.last).as_secs_f64();
self.tokens = (self.tokens + elapsed * self.refill_per_sec).min(self.capacity);
self.last = now;
}

pub fn try_acquire(&mut self, n: f64) -> bool {
self.refill(Instant::now());
if self.tokens >= n {
self.tokens -= n;
true
} else {
false
}
}
}

pub struct Sharded {
shards: Vec<Mutex<HashMap<String, Bucket>>>,
capacity: f64,
refill: f64,
}

impl Sharded {
pub fn new(num_shards: usize, capacity: f64, refill: f64) -> Self {
let mut shards = Vec::with_capacity(num_shards);
for _ in 0..num_shards { shards.push(Mutex::new(HashMap::new())); }
Self { shards, capacity, refill }
}

fn shard_for(&self, key: &str) -> MutexGuard<HashMap<String, Bucket>> {
let h = key.bytes().fold(0u64, |a, b| a.wrapping_mul(131).wrapping_add(b as u64));
self.shards[(h as usize) % self.shards.len()].lock().unwrap()
}

pub fn allow(&self, key: &str) -> bool {
let mut g = self.shard_for(key);
let b = g.entry(key.to_string()).or_insert_with(|| Bucket::new(self.capacity, self.refill));
b.try_acquire(1.0)
}
}

