#pragma once

#include <array>
#include <atomic>
#include <cstddef>

namespace vorberg::ecu {

template <typename T, std::size_t N>
class RingBuffer {
static_assert((N & (N - 1)) == 0, "N muss Zweierpotenz sein");
public:
bool push(const T& value) noexcept {
const auto head = head_.load(std::memory_order_relaxed);
const auto next = (head + 1) & (N - 1);
if (next == tail_.load(std::memory_order_acquire)) return false;
data_[head] = value;
head_.store(next, std::memory_order_release);
return true;
}
bool pop(T& out) noexcept {
const auto tail = tail_.load(std::memory_order_relaxed);
if (tail == head_.load(std::memory_order_acquire)) return false;
out = data_[tail];
tail_.store((tail + 1) & (N - 1), std::memory_order_release);
return true;
}
private:
std::array<T, N> data_{};
std::atomic<std::size_t> head_{0}, tail_{0};
};

} // namespace vorberg::ecu

func (c *ServerConfig) ReqTimeout() time.Duration {
// 5s for queue waiting, computation and disk IO delay
// + 2 * election timeout for possible leader election
return 5*time.Second + 2*time.Duration(c.ElectionTicks*int(c.TickMs))*time.Millisecond
}

function parseSegments(buffer) {
if (buffer.length == 0) throw new Error("bad segments stream");

let pointer = 0;
let segments = [ ];

while (pointer < buffer.length) {
let seg = parseSegment(buffer, pointer);
segments.push(seg);
pointer += seg.bufferLength;
delete seg.bufferLength;
}

if (pointer != buffer.length) {
throw new Error("Bad / incomplete segments");
}

return segments;
}

func WithSort(target SortTarget, order SortOrder) OpOption {
return func(op *Op) {
if target == SortByKey && order == SortAscend {
// If order != SortNone, server fetches the entire key-space,
// and then applies the sort and limit, if provided.
// Since by default the server returns results sorted by keys
// in lexicographically ascending order, the client should ignore
// SortOrder if the target is SortByKey.
order = SortNone
}
op.sort = &SortOption{target, order}
}
}

